function dispatch(msg) {
  if (!msg) return;
  const result = update(model, msg);
  model = result[0];
  render(model);
  if (result[1]) run(result[1]);
}

async function run(cmd) {
  if (!cmd) return;
  if (cmd.__gothicBatch) {
    await Promise.all(cmd.__gothicBatch.map((sub) => run(sub)));
    return;
  }
  if (cmd.__gothicSequence) {
    for (const sub of cmd.__gothicSequence) {
      await run(sub);
    }
    return;
  }
  const msg = await cmd();
  if (msg) {
    dispatch(msg);
  }
}

function emit(msg) { dispatch(msg); }

function init() {
  return null;
}

function update(m, msg) {
  switch (msg.tag) {
  case "LocationChanged":
  {
    m.Path = msg.Path;
    switch (msg.Path) {
    case "/":
      m.Page = "overview";
      break;
    case "/button":
      m.Page = "button";
      break;
    case "/card":
      m.Page = "card";
      break;
    case "/field":
      m.Page = "field";
      break;
    case "/tabs":
      m.Page = "tabs";
      break;
    case "/accordion":
      m.Page = "accordion";
      break;
    case "/disclosure":
      m.Page = "disclosure";
      break;
    case "/conditionals":
      m.Page = "conditionals";
      break;
    case "/stateful-lists":
      m.Page = "stateful-lists";
      break;
    case "/server-state":
      m.Page = "server-state";
      break;
    default:
      m.Page = "notfound";
      break;
    }
    break;
  }
  case "ButtonClicked":
  {
    return [m, async () => {
  window.alert("Hello from Gothicbook");
  return null;
}];
    break;
  }
  case "IncrementClicked":
  {
    return [m, async () => {
  let count, err;
  try {
    count = await Increment();
  } catch (__gothicErr1) {
    err = __gothicErr1;
  }
  if (err != null) {
    return {tag: "CountFailed", Message: err.message};
  }
  return {tag: "CountUpdated", Count: count};
}];
    break;
  }
  case "CountUpdated":
  {
    m.Count = msg.Count;
    break;
  }
  case "ToggleExample":
  {
    m.ShowExample = !m.ShowExample;
    break;
  }
  case "FewerTabs":
  {
    m.Tabs = m.FewTabs;
    break;
  }
  case "MoreTabs":
  {
    m.Tabs = m.ManyTabs;
    break;
  }
  case "NextPage":
  {
    m.ListPage = 1;
    m.Visible = m.PageTwo;
    m.PageLabel = "Showing 11-20 of 20";
    break;
  }
  case "PrevPage":
  {
    m.ListPage = 0;
    m.Visible = m.PageOne;
    m.PageLabel = "Showing 1-10 of 20";
    break;
  }
  case "FieldTextChanged":
  {
    m.FieldText = msg.Text;
    break;
  }
  }
  return [m, null];
}

render(model);
run(init());
function locationMessage() {
  return {tag: "LocationChanged", Path: window.location.pathname, Query: window.location.search, Hash: window.location.hash};
}

function navigate(path) {
  history.pushState(null, "", path);
  dispatch(locationMessage());
}

function replaceLocation(path) {
  history.replaceState(null, "", path);
  dispatch(locationMessage());
}

function routeClick(event) {
  if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
  const el = event.currentTarget;
  if (!el || !el.hasAttribute("href")) return;
  if (el.hasAttribute("download")) return;
  if (el.target && el.target !== "_self") return;
  const url = new URL(el.href, location.href);
  if (url.origin !== location.origin) return;
  event.preventDefault();
  navigate(url.pathname + url.search + url.hash);
}

window.addEventListener("popstate", () => dispatch(locationMessage()));
dispatch(locationMessage());
